import{_ as s,o as a,c as e,a8 as i}from"./chunks/framework.BppdKxCY.js";const k=JSON.parse('{"title":"EP.58 一个账号，全家通行","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.58-unified-account-center.md","filePath":"comics/EP.58-unified-account-center.md","lastUpdated":1792817913000}'),n={name:"comics/EP.58-unified-account-center.md"};function o(r,t,l,d,p,h){return a(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="ep-58-一个账号-全家通行" tabindex="-1">EP.58 一个账号，全家通行 <a class="header-anchor" href="#ep-58-一个账号-全家通行" aria-label="Permalink to &quot;EP.58 一个账号，全家通行&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../44-account-center">第四十四部分 · 多系统统一账号中心</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君在 OA、CRM、工单、数据平台之间来回切换，改个密码要跑三个页面。四套系统各写一遍 <code>login.vue</code> / <code>register.vue</code> / <code>reset.vue</code>，一共 12 个页面，密码策略、错误文案、审计入口各有四份。</li><li><strong>第 2 格</strong>：码叔点破关键——身份只在一处产生，会话在各处短暂存在。业务系统只做三件事：302 到中心登录页、后端用 ticket 换用户信息、种下本地短会话。全局会话只存在中心域，ticket 60 秒、单次、绑定 appId。</li><li><strong>第 3 格</strong>：像素酱验证回跳安全。<code>redirect</code> 参数不能直接信任，必须 <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/URL" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>new URL()</code></a> 解析后逐项校验 protocol、origin、path；<code>oa.example.com.evil.com</code> 与 <code>oa.example.com@evil.com</code> 都会被拦下，回调时还要核对 state。</li><li><strong>第 4 格</strong>：码叔结案——改密撤销其它端会话，重置撤销全部会话；找回入口无论账号是否存在都返回「已发送」。提示「该手机号未注册」等于免费提供账号枚举接口。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-四套账号的代价" tabindex="-1">第 1 格 · 四套账号的代价 <a class="header-anchor" href="#第-1-格-·-四套账号的代价" aria-label="Permalink to &quot;第 1 格 · 四套账号的代价&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>login.vue  register.vue  reset.vue</span></span>
<span class="line"><span>× 4 套系统 = 12 个页面</span></span></code></pre></div><p>复制页面的成本不只是 12 个文件，而是四份会各自漂移的安全策略：</p><table tabindex="0"><thead><tr><th>维度</th><th>各写一遍的后果</th></tr></thead><tbody><tr><td>密码策略</td><td>有的要求 8 位，有的要求 12 位，用户困惑</td></tr><tr><td>错误文案</td><td>有的提示「密码错误」，有的提示「账号不存在」</td></tr><tr><td>验证码</td><td>有的发短信，有的不发，被刷成本不同</td></tr><tr><td>审计日志</td><td>四套格式，出事时拼不出完整时间线</td></tr></tbody></table><p>账号数据也各存一份：员工离职后要在四个后台分别停用，漏一个就是遗留权限。</p><h3 id="第-2-格-·-三层会话与一次性票据" tabindex="-1">第 2 格 · 三层会话与一次性票据 <a class="header-anchor" href="#第-2-格-·-三层会话与一次性票据" aria-label="Permalink to &quot;第 2 格 · 三层会话与一次性票据&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 302 → account.example.com/login?redirect=...</span></span>
<span class="line"><span>2. 后端 POST /sso/redeem { ticket } → 用户信息</span></span>
<span class="line"><span>3. Set-Cookie: 本地会话（30min）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>层</th><th>存放位置</th><th>生命周期</th><th>作用</th></tr></thead><tbody><tr><td>全局会话</td><td>中心域 HttpOnly Cookie</td><td>空闲 2 小时</td><td>真正的「已登录」</td></tr><tr><td>一次性 ticket</td><td>URL 参数，60 秒</td><td>单次</td><td>中心 → 业务系统的换票凭证</td></tr><tr><td>本地会话</td><td>业务域 Cookie / JWT</td><td>30 分钟</td><td>业务系统自己认的凭证</td></tr></tbody></table><p>ticket 必须同时满足<strong>单次消费</strong>、<strong>绑定 appId</strong>、<strong>短 TTL</strong> 三个条件：只单次不绑定时，A 系统的票可换 B 系统会话；只绑定不设 TTL 时，泄露的票可长期复用。</p><p>完整实现见 <a href="../examples/44-02-login-ticket.ts">44-02-login-ticket.ts</a> 与 <a href="../examples/44-04-sso-slo.ts">44-04-sso-slo.ts</a>。</p><h3 id="第-3-格-·-回跳白名单四道关" tabindex="-1">第 3 格 · 回跳白名单四道关 <a class="header-anchor" href="#第-3-格-·-回跳白名单四道关" aria-label="Permalink to &quot;第 3 格 · 回跳白名单四道关&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(redirect)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (u.protocol </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (u.origin </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.origin) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pathOk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(u.pathname)) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>四道关的顺序不能省：</p><ol><li><strong>协议</strong>：只允许 <code>https:</code>，挡掉 <code>javascript:</code> 与 <code>http:</code> 降级；</li><li><strong>userinfo</strong>：<code>oa.example.com@evil.com</code> 的实际 host 是 <code>evil.com</code>，解析后 origin 不匹配即拦；</li><li><strong>origin</strong>：精确比较，挡掉 <code>oa.example.com.evil.com</code> 这类后缀伪装；</li><li><strong>path</strong>：只允许登记过的路径前缀，避免开放站内跳转被拿来做钓鱼落地页。</li></ol><p>此外发起时生成随机 <code>state</code> 存进会话，回调时原样比对，防止登录 CSRF。八种攻击形态的完整用例在 <a href="../examples/44-03-redirect-whitelist.ts">44-03-redirect-whitelist.ts</a>。</p><h3 id="第-4-格-·-改密撤会话与防枚举" tabindex="-1">第 4 格 · 改密撤会话与防枚举 <a class="header-anchor" href="#第-4-格-·-改密撤会话与防枚举" aria-label="Permalink to &quot;第 4 格 · 改密撤会话与防枚举&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>changePassword → revoke all but current</span></span>
<span class="line"><span>resetPassword  → revoke ALL sessions</span></span>
<span class="line"><span>requestReset   → 假成功，防账号枚举</span></span></code></pre></div><p>两个入口的安全语义不同：</p><table tabindex="0"><thead><tr><th>入口</th><th>前置条件</th><th>会话处理</th><th>理由</th></tr></thead><tbody><tr><td>修改密码</td><td>已登录 + 验旧密码</td><td>撤销除当前会话外全部</td><td>用户正在操作，保留当前体验</td></tr><tr><td>找回密码</td><td>手机验证码</td><td>撤销全部会话</td><td>账号可能已失陷，全部重新登录</td></tr></tbody></table><p>重置令牌只存哈希、15 分钟、单次使用；找回入口无论手机号是否存在都返回「已发送」，避免把注册接口变成账号枚举器。实现见 <a href="../examples/44-05-password-change-reset.ts">44-05-password-change-reset.ts</a>。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../44-account-center#_44-8-本章避坑清单">《44.8 本章避坑清单》</a></p></blockquote><ol><li><strong>每套系统各写一遍身份页面</strong>：策略与文案必然漂移。统一到账号中心，业务系统只保留接入代码。</li><li><strong>ticket 不设单次或不绑 appId</strong>：票据被截获后可换任意系统的会话。三个条件必须同时满足。</li><li><strong><code>redirect</code> 直接 <code>location.href</code></strong>：开放重定向，真域名把人送去钓鱼站。必须解析 URL 后逐项校验。</li><li><strong>只校验 origin 不校验 protocol</strong>：<code>javascript:</code> 伪协议仍可能执行。协议、userinfo、origin、path 四道关缺一不可。</li><li><strong>改密后不撤会话</strong>：旧设备上的会话继续有效，等于密码泄露后没止损。</li><li><strong>找回密码提示「账号不存在」</strong>：免费提供账号枚举接口。统一返回「已发送」。</li></ol><h2 id="自测-3-题" tabindex="-1">自测 3 题 <a class="header-anchor" href="#自测-3-题" aria-label="Permalink to &quot;自测 3 题&quot;">​</a></h2><p><strong>1. 为什么登录页的编排要「先检查锁定，再验密」？</strong></p><details><summary>参考答案</summary><p>如果先验密再查锁定，攻击者每次尝试都会触发一次真实的密码哈希计算与数据库比对，锁定形同虚设，还会给服务端带来无谓的 scrypt 计算开销。先检查失败计数与锁定截止时间，可在爆破进行到第 6 次时直接拒绝，不消耗验密资源；同时锁定时仍要返回与密码错误一致的文案，避免泄露「这个账号存在且已被锁」。</p></details><p><strong>2. 一次性 ticket 为什么必须同时满足「单次、绑定 appId、短 TTL」？</strong></p><details><summary>参考答案</summary><p>单次消费防止重放：票据被浏览器历史、日志或 Referer 泄露后无法二次使用。绑定 appId 防止横向越权：A 系统签发的票不能在 B 系统兑换，否则任意接入方都能拿到别家用户。短 TTL 把泄露窗口压到 60 秒内，即使前两条都被绕过，票据也很快失效。三者是正交的防线，缺一条都会留下可利用的缺口。</p></details><p><strong>3. 修改密码和重置密码在「撤销会话」上为什么策略不同？</strong></p><details><summary>参考答案</summary><p>修改密码是已登录用户在正常操作，且已经验证过旧密码，威胁模型是「其它设备可能已泄露」——因此撤销除当前会话外的全部会话，既止损又保留用户当前体验。重置密码发生在未登录场景，只能靠手机验证码证明身份，威胁模型应假设账号已经失陷——因此撤销全部会话（包括可能存在的攻击者会话），要求所有端重新用新密码登录。</p></details>`,35)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
